291	        LocalDate on = from != null ? from : sheets.today(sheetId);
292	        if (to != null && to.isBefore(on)) {
293	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
294	        }
295	        Rollup.Figures before = rollup.figures(sheetId);
296	        person.hold(on, to);
297	        people.flush();
298	        events.publishEvent(new PersonHeld(sheetId, user, person.getName(), on));
299	        rollup.changed(sheetId, user, before);
300	        return person;
301	    }
302	
303	    /**
304	     * A steward flags the person with a reason, stored trimmed, until a date (none: the sheet's today). Anyone
305	     * but a steward, or a blank reason, is refused. Takes turns with other changes on the sheet.
306	     */
307	    @Transactional
308	    public Person flag(String sheetId, String user, long personId, String reason, LocalDate until) {
309	        sheetRows.lockById(sheetId);
310	        Person person = get(sheetId, personId);
311	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
312	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can flag a person");
313	        }
314	        String trimmed = reason == null ? "" : reason.trim();
315	        if (trimmed.isEmpty()) {
316	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Give a reason");
317	        }
318	        LocalDate on = until != null ? until : sheets.today(sheetId);
319	        person.flag(trimmed, on);
320	        people.flush();
321	        events.publishEvent(new PersonFlagged(sheetId, user, person.getName(), trimmed, on));
322	        return person;
323	    }
324	
325	    /**
326	     * Give the person an approver: a user name, stored trimmed, who may approve or reject their PENDING claims
327	     * as a steward may. A blank name is refused. Takes turns with other changes on the sheet.
328	     */
329	    @Transactional
330	    public Person setApprover(String sheetId, String user, long personId, String approver) {
331	        sheetRows.lockById(sheetId);
332	        Person person = get(sheetId, personId);
333	        String trimmed = approver == null ? "" : approver.trim();
334	        if (trimmed.isEmpty()) {
335	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Give a user name");
336	        }
337	        person.setApprover(trimmed);
338	        people.flush();
339	        events.publishEvent(new ApproverSet(sheetId, user, person.getName(), trimmed));
340	        return person;
341	    }
342	
343	    /**
344	     * The person on the sheet whose name or an alias is the given one, compared without regard to case.
345	     */
346	    @Transactional(readOnly = true)
347	    public Optional<Person> findByNameOrAlias(String sheetId, String name) {
348	        return people.findBySheetIdAndNameOrAlias(sheetId, name.trim()).stream().findFirst();
349	    }
350	
351	    /**
352	     * Give the person an alias, stored trimmed. A blank alias, or one equal (without regard to case) to any
353	     * name or alias on a sheet of the sheet's tree, is
354	     * refused. Takes turns with other changes on the sheet.
355	     */
356	    @Transactional
357	    public Person addAlias(String sheetId, String user, long personId, String alias) {
358	        sheetRows.lockById(sheetId);
359	        Person person = get(sheetId, personId);
360	        String trimmed = alias == null ? "" : alias.trim();
361	        if (trimmed.isEmpty()) {
362	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Give an alias");
363	        }
364	        if (inUse(sheetId, trimmed, null)) {
365	            throw nameInUse();
366	        }
367	        person.addAlias(trimmed);
368	        people.flush();
369	        events.publishEvent(new PersonAliasAdded(sheetId, user, person.getName(), trimmed));
370	        return person;
371	    }
372	
373	    /**
374	     * A person found by {@link #search}: their sheet, name, grade in force on their sheet's today and due-total
375	     * as shown ({@code n/a} when none).
376	     */
377	    public record Found(String sheetId, String name, String grade, String dueTotal) {
378	    }
379	
380	    /**
381	     * Every person on a sheet of the sheet's tree (see {@link SheetService#tree}) whose name or an alias
382	     * contains the text, compared without regard to case (blank: everyone): the sheet's own people first in
383	     * list order, then the other sheets' by sheet id, each in its list order.
384	     */
385	    @Transactional(readOnly = true)
386	    public List<Found> search(String sheetId, String text) {
387	        String key = key(text == null ? "" : text.trim());
388	        List<String> others = new ArrayList<>(sheets.tree(sheetId));
389	        others.remove(sheetId);
390	        Collections.sort(others);
391	        List<String> order = new ArrayList<>(List.of(sheetId));
392	        order.addAll(others);
393	        List<Found> found = new ArrayList<>();
394	        for (String sheet : order) {
395	            Map<Long, Rollup.PersonFigures> figures = rollup.figures(sheet).people();
396	            LocalDate today = sheets.today(sheet);
397	            for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheet)) {
398	                if (names(p).stream().anyMatch(n -> n.contains(key))) {
399	                    Rollup.PersonFigures f = figures.get(p.getId());
400	                    found.add(new Found(sheet, p.getName(), p.gradeOn(today), f == null ? "n/a" : f.dueTotal()));
401	                }
402	            }
403	        }
404	        return found;
405	    }
406	
407	    /**
408	     * Whether a person on a sheet of the sheet's tree (see {@link SheetService#tree}), other than the one with
409	     * the id (none: any), has the name or alias, compared without regard to case.
410	     */
411	    @Transactional(readOnly = true)
412	    public boolean inUse(String sheetId, String name, Long exceptId) {
413	        String key = key(name);
414	        return people.findBySheetIdIn(sheets.tree(sheetId)).stream()
415	                .filter(p -> !p.getId().equals(exceptId))
416	                .anyMatch(p -> names(p).contains(key));
417	    }
418	
419	    /**
420	     * The ids of the people on the sheet who clash: whose name or an alias another person on a sheet of the
421	     * sheet's tree also has, compared without regard to case. People who clashed before names became unique
422	     * across a tree keep their names; each edit of them is refused until they no longer clash.
423	     */
424	    @Transactional(readOnly = true)
425	    public Set<Long> clashing(String sheetId) {
426	        Map<String, Set<Long>> holders = new HashMap<>();
427	        for (Person p : people.findBySheetIdIn(sheets.tree(sheetId))) {
428	            for (String name : names(p)) {
429	                holders.computeIfAbsent(name, n -> new HashSet<>()).add(p.getId());
430	            }
431	        }
432	        Set<Long> clashing = new HashSet<>();
433	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
434	            if (names(p).stream().anyMatch(n -> holders.getOrDefault(n, Set.of()).stream()
435	                    .anyMatch(id -> !id.equals(p.getId())))) {
436	                clashing.add(p.getId());
437	            }
438	        }
439	        return clashing;
440	    }
441	
442	    /** Whether the person clashes (see {@link #clashing(String)}). */
443	    @Transactional(readOnly = true)
444	    public boolean clashing(String sheetId, Person person) {
445	        return inUse(sheetId, person.getName(), person.getId())
446	                || person.getAliases().stream().anyMatch(alias -> inUse(sheetId, alias, person.getId()));
447	    }
448	
449	    private static Set<String> names(Person person) {
450	        Set<String> names = new HashSet<>();
451	        names.add(key(person.getName()));
452	        person.getAliases().forEach(alias -> names.add(key(alias)));
453	        return names;
454	    }
455	
456	    private static String key(String name) {
457	        return name.trim().toLowerCase(Locale.ROOT);
458	    }
459	
460	    /** The ids of each person's patrons on the sheet, by person id, in the order they were named. */
461	    @Transactional(readOnly = true)
462	    public Map<Long, List<Long>> patronsBySheet(String sheetId) {
463	        return patrons.findBySheetIdOrderByIdAsc(sheetId).stream().collect(Collectors.groupingBy(
464	                Patron::getPersonId, Collectors.mapping(Patron::getPatronId, Collectors.toList())));
465	    }
466	
467	    /** Each person's snapshot lines on the sheet, by person id, oldest first. */
468	    @Transactional(readOnly = true)
469	    public Map<Long, List<PersonSnapshot>> snapshotsBySheet(String sheetId) {
470	        return snapshots.findBySheetIdOrderByIdAsc(sheetId).stream()
471	                .collect(Collectors.groupingBy(PersonSnapshot::getPersonId));
472	    }
473	
474	    /** The person's snapshot lines, oldest first. */
475	    @Transactional(readOnly = true)
476	    public List<PersonSnapshot> snapshots(String sheetId, long personId) {
477	        return snapshots.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
478	    }
479	
480	    /** The ids of the person's patrons, in the order they were named. */
481	    @Transactional(readOnly = true)
482	    public List<Long> patrons(String sheetId, long personId) {
483	        return patrons.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId).stream()
484	                .map(Patron::getPatronId).toList();
485	    }
486	
487	    /**
488	     * The person names another person on the sheet as their patron. Naming themselves, someone not on
489	     * the sheet or someone already their patron is refused. Takes turns with other changes on the sheet.
490	     */
491	    @Transactional
492	    public Person addPatron(String sheetId, String user, long personId, long patronId) {
493	        sheetRows.lockById(sheetId);
494	        Person person = get(sheetId, personId);
495	        if (patronId == personId) {
496	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron");
497	        }
498	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
499	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "No such person"));
500	        if (patrons.existsByPersonIdAndPatronId(personId, patronId)) {
501	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Already a patron");
502	        }
503	        patrons.saveAndFlush(new Patron(sheetId, personId, patronId));
504	        events.publishEvent(new PatronAdded(sheetId, user, person.getName(), patron.getName()));
505	        return person;
506	    }
507	
508	    /** Someone else saved the person after the editor loaded them. */
509	    public static ResponseStatusException edited() {
510	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Saved by someone else since loaded");
511	    }
512	
513	    private static ResponseStatusException nameInUse() {
514	        return new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use");
515	    }
516	
517	    private static ResponseStatusException contactInUse() {
518	        return new ResponseStatusException(HttpStatus.CONFLICT, "Contact already in use");
519	    }
520	}
