tool_use_result.originalFile:
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.sheet.DatedSettings;

/**
 * Every rate on a sheet, the sheet's today, its dated settings (the floor in force on a claim's date, the late
 * percent in force on each 30-day boundary past its due-by, the cap in force on the sheet's today) and its policy date (null: the sheet's today): which rate is in force for a grade on a date, the live due it
 * makes of an amount, the late charge an overdue figure gains, how a claim's figures round, and the most a
 * person's due-total comes to. A grade with no rate in force on a date takes the rate of the parent sheet's
 * rates on that date, then the parent's parent, up to three levels up; then, for a sheet that was cloned, the
 * sheet it was cloned from and so on up its parents and source ({@code ancestors}, nearest first, see
 * {@link ParentRates}).
 */
public record RateTable(List<Rate> rates, LocalDate today, DatedSettings settings, LocalDate policyDate,
        List<List<Rate>> ancestors) {

    /** How many levels of parent sheets a grade's rate is looked for in, from a sheet or from a source sheet. */
    public static final int ANCESTOR_LEVELS = 3;

    /** A sheet's rates with no parent sheet to fall back on. */
    public RateTable(List<Rate> rates, LocalDate today, DatedSettings settings, LocalDate policyDate) {
        this(rates, today, settings, policyDate, List.of());
    }

    /** The days in each period overdue that adds the late percent once more. */
    private static final int LATE_PERIOD_DAYS = 30;

    /**
     * The percent in force for the grade on the date: the rate whose from-date is the latest one on
     * or before it, a rate with no from-date applying from the beginning of time; null when none does,
     * or when that rate's to-date is before the date (it has ended, and no later rate is in force). When
     * this sheet has none in force, the parent sheet's, then its parent's, up to three levels up, then the
     * source sheet's of a clone.
     */
    public BigDecimal on(String grade, LocalDate date) {
        return on(grade, date, null);
    }

    /**
     * The percent in force for the grade on the date for the claim with the id given, as {@link #on(String, LocalDate)}
     * but leaving out the forward-only rates saved before the claim was added (see {@link Rate#appliesTo}); a null
     * id leaves out none.
     */
    public BigDecimal on(String grade, LocalDate date, Long claimId) {
        BigDecimal pct = on(rates, grade, date, claimId);
        for (int i = 0; pct == null && i < ancestors.size(); i++) {
            pct = on(ancestors.get(i), grade, date, claimId);
        }
        return pct;
    }

    private static BigDecimal on(List<Rate> rates, String grade, LocalDate date, Long claimId) {
        return latest(rates.stream().filter(r -> r.appliesTo(claimId)).toList(), grade, date)
                .filter(r -> !ended(r, date)).map(Rate::getPct).orElse(null);
    }

    /**
     * Whether the grade has no rate on the date (here or on a parent sheet) only because a rate that would
     * apply has ended by then.
     */
    public boolean ended(String grade, LocalDate date) {
        if (on(grade, date) != null) {
            return false;
        }
        boolean ended = latest(rates, grade, date).isPresent();
        for (int i = 0; !ended && i < ancestors.size(); i++) {
            ended = latest(ancestors.get(i), grade, date).isPresent();
        }
        return ended;
    }

    /** The grade's rate with the latest from-date on or before the date, ended or not. */
    private static Optional<Rate> latest(List<Rate> rates, String grade, LocalDate date) {
        return rates.stream()
                .filter(r -> r.getGrade().equals(grade))
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())));
    }

    private static boolean ended(Rate rate, LocalDate date) {
        return rate.getToDate() != null && rate.getToDate().isBefore(date);
    }

    /** The cap in force on the sheet's today: the most a person's due-total comes to; null when there is none. */
    public BigDecimal cap() {
        return settings.cap(today);
    }

    /** A due-total held to the cap: the cap when the sum is above it; as it is otherwise, or when n/a (null). */
    public BigDecimal capped(BigDecimal sum) {
        BigDecimal cap = cap();
        return sum == null || cap == null || sum.compareTo(cap) <= 0 ? sum : cap;
    }

    /** What a due-total's sum is above the cap: 0.00 when it is not, or when n/a (null). */
    public BigDecimal excess(BigDecimal sum) {
        BigDecimal cap = cap();
        return sum == null || cap == null || sum.compareTo(cap) <= 0 ? BigDecimal.ZERO : sum.subtract(cap);
    }

    /**
     * A due-total held to the cap less the person's cut total (not below 0.00): that when the sum is above it; as it
     * is otherwise, or when n/a (null).
     */
    public BigDecimal capped(BigDecimal sum, BigDecimal cut) {
        BigDecimal cap = cap();
        if (sum == null || cap == null) {
            return sum;
        }
        BigDecimal room = cap.subtract(cut).max(BigDecimal.ZERO);
        return sum.compareTo(room) <= 0 ? sum : room;
    }

    /**
     * What a due-total's sum plus the person's cut total is above the cap: 0.00 when it is not, or when n/a (null).
     */
    public BigDecimal excess(BigDecimal sum, BigDecimal cut) {
        return sum == null ? BigDecimal.ZERO : excess(sum.add(cut));
    }

    /** The percent in force for the grade on the sheet's today; null when none is. */
    public BigDecimal current(String grade) {
        return on(grade, today);
    }

    /**
     * How the figures of a claim whose rounding goes by the date round: by the rounding mode in force on
     * that date when one is; otherwise half up when it is before the policy date (the sheet's today when
     * none is set), half to even on or after it.
     */
    public RoundingMode rounding(LocalDate roundsBy) {
        RoundingMode mode = settings.rounding(roundsBy);
        if (mode != null) {
            return mode;
        }
        LocalDate policy = policyDate == null ? today : policyDate;
        return roundsBy.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /**
     * The rate figure of an amount dated on the date for the grade: the amount at the rate in force then,
     * rounded by the date, with no floor; null when no rate is.
     */
    public BigDecimal figure(BigDecimal amount, String grade, LocalDate date) {
        return figure(amount, grade, date, null);
    }

    /** The rate figure of the claim with the id given, as {@link #figure(BigDecimal, String, LocalDate)} at the rate in force for it, see {@link #on(String, LocalDate, Long)}. */
    public BigDecimal figure(BigDecimal amount, String grade, LocalDate date, Long claimId) {
        return RateService.due(amount, on(grade, date, claimId), rounding(date));
    }

    /** A live due held up to the floor in force on the date: the greater of the two; null when the due is. */
    public BigDecimal floored(BigDecimal due, LocalDate date) {
        BigDecimal floor = settings.floor(date);
        return due == null || floor == null || due.compareTo(floor) >= 0 ? due : floor;
    }

    /**
     * The late charge on a figure of a claim due by the due-by: for every full 30 days from its due-by to the
     * sheet's today, the late percent in force on that boundary date (the due-by plus 30, 60, 90 ... days) of
     * the figure plus the charges of the boundaries before it (compounding), each rounded by the date its claim's rounding goes by, added up; a boundary whose percent is
     * 0.00 adds nothing. 0.00 when not a full 30 days overdue.
     */
    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy, LocalDate roundsBy) {
        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / LATE_PERIOD_DAYS : 0;
        RoundingMode rounding = rounding(roundsBy);
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = settings.latePct(dueBy.plusDays(n * LATE_PERIOD_DAYS));
            if (pct.signum() != 0) {
                charge = charge.add(RateService.due(figure.add(charge), pct, rounding));
            }
        }
        return charge;
    }
}
